PREFIX brick: <https://brickschema.org/schema/1.2/brick#>
PREFIX ref: <http://rdg.harmonomi.com/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?id ?name ?pclass WHERE {
  ?p a brick:ElectricPower ;
     brick:hasInputSystem ?comp ;
     ref:hasTimeseriesId ?id .
  ?comp a ?compType ; rdfs:label ?name .
  ?p a ?pclass .
}

PREFIX brick: <https://brickschema.org/schema/1.2/brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?uri ?type ?label WHERE {
  ?uri a ?type ; rdfs:label ?label .
} LIMIT 50

SELECT ?uri ?type ?props WHERE {
  ?uri a ?type .
  FILTER(CONTAINS(str(?uri), "Chiller01") || CONTAINS(str(?uri), "AHU01"))
} LIMIT 100

SELECT ?ts ?ref WHERE {
  ?ts a brick:Electric_Power_Sensor .
  ?ts rdfs:label ?label .
  FILTER(CONTAINS(str(?label), "Chiller1") && !CONTAINS(str(?label), "Pump"))
  OPTIONAL {
    ?ts ref:hasExternalReference ?ref .
  }
}

